/**
 * Aggregates sellable offers into one ProductCard per product.
`fromPricePesewas` is the cheapest sellable offer; `offerCount` is the
number of sellable peer offers. No product-level price.

 * @summary Product-centric catalog (one card per product)
 */
export const getGetCatalogUrl = (params?: GetCatalogParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : value.toString())
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/store/catalog?${stringifiedParams}` : `/store/catalog`
}

export const getCatalog = async (params?: GetCatalogParams, options?: RequestInit): Promise<CatalogListResponse> => {
  
  return customFetch<CatalogListResponse>(getGetCatalogUrl(params),
  {      
    ...options,
    method: 'GET'
    
    
  }
);}



